(() => {
  const state = {
    gpsEnabled: false,
    fakeGeo: null,
    languageEnabled: false,
    navigatorLanguage: '',
    navigatorLanguages: [],
    userAgentEnabled: false,
    userAgent: '',
    platform: '',
    userAgentData: null,
    fingerprintingEnabled: false,
    fingerprintProfile: null
  };

  const original = {
    getCurrentPosition: navigator.geolocation?.getCurrentPosition?.bind(navigator.geolocation),
    watchPosition: navigator.geolocation?.watchPosition?.bind(navigator.geolocation),
    clearWatch: navigator.geolocation?.clearWatch?.bind(navigator.geolocation),
    permissionQuery: navigator.permissions?.query?.bind(navigator.permissions),
    language: navigator.language,
    languages: Array.isArray(navigator.languages) ? navigator.languages.slice() : [navigator.language].filter(Boolean),
    userAgent: navigator.userAgent,
    appVersion: navigator.appVersion,
    platform: navigator.platform,
    vendor: navigator.vendor,
    maxTouchPoints: navigator.maxTouchPoints,
    userAgentData: navigator.userAgentData
  };
  const originalDateTimezoneOffset = Date.prototype.getTimezoneOffset;
  const originalIntlResolvedOptions = Intl.DateTimeFormat.prototype.resolvedOptions;
  const originalCanvasToDataURL = HTMLCanvasElement.prototype.toDataURL;
  const originalCanvasToBlob = HTMLCanvasElement.prototype.toBlob;
  const originalGetImageData = CanvasRenderingContext2D?.prototype?.getImageData;
  const originalGetChannelData = AudioBuffer?.prototype?.getChannelData;
  const originalGetFloatFrequencyData = AnalyserNode?.prototype?.getFloatFrequencyData;
  const originalWebGLGetParameter = WebGLRenderingContext?.prototype?.getParameter;
  const originalWebGL2GetParameter = WebGL2RenderingContext?.prototype?.getParameter;
  const originalWebGLBufferData = WebGLRenderingContext?.prototype?.bufferData;
  const originalWebGL2BufferData = WebGL2RenderingContext?.prototype?.bufferData;
  const htmlOffsetWidthDescriptor = typeof HTMLElement !== 'undefined'
    ? Object.getOwnPropertyDescriptor(HTMLElement.prototype, 'offsetWidth')
    : null;
  const originalFunctionToString = Function.prototype.toString;
  const nativeSourceByFunction = new WeakMap();
  const navigatorHardwareDescriptor = Object.getOwnPropertyDescriptor(Navigator.prototype, 'hardwareConcurrency');
  const navigatorMemoryDescriptor = Object.getOwnPropertyDescriptor(Navigator.prototype, 'deviceMemory');
  const screenWidthDescriptor = typeof Screen !== 'undefined' ? Object.getOwnPropertyDescriptor(Screen.prototype, 'width') : null;
  const screenHeightDescriptor = typeof Screen !== 'undefined' ? Object.getOwnPropertyDescriptor(Screen.prototype, 'height') : null;
  const screenAvailWidthDescriptor = typeof Screen !== 'undefined' ? Object.getOwnPropertyDescriptor(Screen.prototype, 'availWidth') : null;
  const screenAvailHeightDescriptor = typeof Screen !== 'undefined' ? Object.getOwnPropertyDescriptor(Screen.prototype, 'availHeight') : null;
  const screenColorDepthDescriptor = typeof Screen !== 'undefined' ? Object.getOwnPropertyDescriptor(Screen.prototype, 'colorDepth') : null;
  const screenPixelDepthDescriptor = typeof Screen !== 'undefined' ? Object.getOwnPropertyDescriptor(Screen.prototype, 'pixelDepth') : null;
  const navigatorUserAgentDescriptor = Object.getOwnPropertyDescriptor(Navigator.prototype, 'userAgent');
  const navigatorAppVersionDescriptor = Object.getOwnPropertyDescriptor(Navigator.prototype, 'appVersion');
  const navigatorPlatformDescriptor = Object.getOwnPropertyDescriptor(Navigator.prototype, 'platform');
  const navigatorVendorDescriptor = Object.getOwnPropertyDescriptor(Navigator.prototype, 'vendor');
  const navigatorMaxTouchPointsDescriptor = Object.getOwnPropertyDescriptor(Navigator.prototype, 'maxTouchPoints');
  const navigatorUserAgentDataDescriptor = Object.getOwnPropertyDescriptor(Navigator.prototype, 'userAgentData');
  let userAgentPatchesInstalled = false;
  let strictPatchesInstalled = false;

  function markNative(fn, name = '', sourceFn = null) {
    if (typeof fn !== 'function') return fn;
    let source = '';
    try {
      if (typeof sourceFn === 'function') source = originalFunctionToString.call(sourceFn);
    } catch (e) {}
    if (!source) {
      const safeName = String(name || fn.name || '').replace(/[^A-Za-z0-9_$ ]/g, '');
      source = `function ${safeName}() { [native code] }`;
    }
    nativeSourceByFunction.set(fn, source);
    return fn;
  }

  // BrowserScan and similar check whether patched browser APIs still look native.
  // The old Make Proxy Simple engine used Proxy wrappers, which naturally hide
  // implementation source. Keep equivalent native-looking Function#toString output.
  try {
    const stealthToString = new Proxy(originalFunctionToString, {
      apply(target, thisArg, args) {
        if (nativeSourceByFunction.has(thisArg)) return nativeSourceByFunction.get(thisArg);
        return Reflect.apply(target, thisArg, args);
      }
    });
    nativeSourceByFunction.set(stealthToString, originalFunctionToString.call(originalFunctionToString));
    Function.prototype.toString = stealthToString;
  } catch (e) {}

  const activeWatchers = new Map();
  let nextWatchId = 9000;

  function buildPosition() {
    if (!state.gpsEnabled || !state.fakeGeo || !Number.isFinite(state.fakeGeo.lat) || !Number.isFinite(state.fakeGeo.lng)) return null;
    return {
      coords: {
        latitude: state.fakeGeo.lat,
        longitude: state.fakeGeo.lng,
        accuracy: 35,
        altitude: null,
        altitudeAccuracy: null,
        heading: null,
        speed: null
      },
      timestamp: Date.now()
    };
  }

  function notifyWatchers() {
    const position = buildPosition();
    if (!position) return;
    for (const success of activeWatchers.values()) {
      try { success(position); } catch (e) {}
    }
  }

  try {
    const geoTarget = window.Geolocation?.prototype || navigator.geolocation;
    if (geoTarget) {
      geoTarget.getCurrentPosition = markNative(function(success, error, options) {
        const position = buildPosition();
        if (position && typeof success === 'function') {
          success(position);
          return;
        }
        return original.getCurrentPosition ? original.getCurrentPosition(success, error, options) : undefined;
      }, 'getCurrentPosition');

      geoTarget.watchPosition = markNative(function(success, error, options) {
        const position = buildPosition();
        if (position && typeof success === 'function') {
          const id = nextWatchId++;
          activeWatchers.set(id, success);
          success(position);
          return id;
        }
        return original.watchPosition ? original.watchPosition(success, error, options) : -1;
      }, 'watchPosition');

      geoTarget.clearWatch = markNative(function(id) {
        activeWatchers.delete(id);
        return original.clearWatch ? original.clearWatch(id) : undefined;
      }, 'clearWatch');
    }
  } catch (e) {}

  if (navigator.permissions?.query) {
    try {
      navigator.permissions.query = markNative(async function(parameters) {
        if (parameters && parameters.name === 'geolocation' && state.gpsEnabled && buildPosition()) {
          return { state: 'granted', onchange: null };
        }
        return original.permissionQuery ? original.permissionQuery(parameters) : Promise.resolve({ state: 'prompt', onchange: null });
      }, 'query');
    } catch (e) {}
  }

  function defineGetter(proto, property, getter) {
    try {
      const descriptor = Object.getOwnPropertyDescriptor(proto, property);
      if (descriptor && !descriptor.configurable) return;
      Object.defineProperty(proto, property, {
        configurable: descriptor ? descriptor.configurable : true,
        enumerable: descriptor ? descriptor.enumerable : true,
        get: markNative(getter, `get ${property}`, descriptor?.get || null)
      });
    } catch (e) {}
  }

  function restorePrototypeProperty(proto, property, descriptor) {
    try {
      if (!proto) return;
      if (descriptor) {
        Object.defineProperty(proto, property, descriptor);
      } else {
        delete proto[property];
      }
    } catch (e) {}
  }

  function cloneBrands(brands) {
    return Array.isArray(brands)
      ? brands.map((brand) => ({
        brand: String(brand?.brand || ''),
        version: String(brand?.version || '')
      })).filter((brand) => brand.brand && brand.version)
      : [];
  }

  function buildNavigatorUAData(profile) {
    if (!profile || typeof profile !== 'object') return original.userAgentData || undefined;
    const highEntropyValues = profile.highEntropyValues && typeof profile.highEntropyValues === 'object'
      ? profile.highEntropyValues
      : {};
    const brands = cloneBrands(profile.brands || highEntropyValues.brands);
    const fullVersionList = cloneBrands(highEntropyValues.fullVersionList);
    const platform = String(profile.platform || highEntropyValues.platform || '');
    const mobile = !!(profile.mobile || highEntropyValues.mobile);
    const values = {
      brands,
      mobile,
      platform,
      architecture: String(highEntropyValues.architecture || ''),
      bitness: String(highEntropyValues.bitness || ''),
      fullVersionList,
      model: String(highEntropyValues.model || ''),
      platformVersion: String(highEntropyValues.platformVersion || ''),
      uaFullVersion: String(highEntropyValues.uaFullVersion || ''),
      wow64: !!highEntropyValues.wow64
    };
    return {
      brands: values.brands.map((brand) => ({ ...brand })),
      mobile: values.mobile,
      platform: values.platform,
      getHighEntropyValues: markNative(function(hints) {
        const result = {
          brands: values.brands.map((brand) => ({ ...brand })),
          mobile: values.mobile,
          platform: values.platform
        };
        const requestedHints = Array.isArray(hints) ? hints.map(String) : [];
        for (const hint of requestedHints) {
          if (hint === 'fullVersionList') {
            result.fullVersionList = values.fullVersionList.map((brand) => ({ ...brand }));
          } else if (Object.prototype.hasOwnProperty.call(values, hint)) {
            result[hint] = values[hint];
          }
        }
        return Promise.resolve(result);
      }, 'getHighEntropyValues'),
      toJSON: markNative(function() {
        return {
          brands: values.brands.map((brand) => ({ ...brand })),
          mobile: values.mobile,
          platform: values.platform
        };
      }, 'toJSON')
    };
  }

  function shouldApplyFingerprinting() {
    return !!(state.fingerprintingEnabled && state.fingerprintProfile);
  }

  function shouldApplyFeature(featureName) {
    if (!shouldApplyFingerprinting()) return false;
    const featureFlags = state.fingerprintProfile?.features;
    if (!featureFlags || typeof featureFlags !== 'object') return true;
    return featureFlags[featureName] !== false;
  }

  function getNumberSalt(value, fallback = 1) {
    const num = Number(value);
    if (!Number.isFinite(num)) return fallback;
    return Math.abs(Math.floor(num)) || fallback;
  }

  function computeTimezoneOffsetMinutes(timezone) {
    const map = {
      'America/New_York': 300,
      'America/Chicago': 360,
      'America/Los_Angeles': 480,
      'Europe/London': 0,
      'Europe/Berlin': -60,
      'Asia/Tokyo': -540,
      'Asia/Ho_Chi_Minh': -420,
      'Asia/Singapore': -480
    };
    return Object.prototype.hasOwnProperty.call(map, timezone) ? map[timezone] : null;
  }

  function getCanvasShift(profile) {
    const existing = profile?.canvasShift && typeof profile.canvasShift === 'object' ? profile.canvasShift : null;
    if (existing) {
      return {
        r: Number(existing.r) || 0,
        g: Number(existing.g) || 0,
        b: Number(existing.b) || 0,
        a: Number(existing.a) || 0
      };
    }
    const salt = getNumberSalt(profile?.canvasSalt, 7);
    const shift = {
      r: (salt % 9) - 4,
      g: (Math.floor(salt / 11) % 9) - 4,
      b: (Math.floor(salt / 101) % 9) - 4,
      a: 0
    };
    if (shift.r === 0 && shift.g === 0 && shift.b === 0) shift.r = 1;
    return shift;
  }

  function patchCanvasPixels(imageData, profile) {
    if (!imageData || !imageData.data || imageData.data.length < 4) return imageData;
    const shift = getCanvasShift(profile);
    const data = imageData.data;
    const pixelCount = Math.floor(data.length / 4);
    const sampleCount = Math.min(4, pixelCount);
    const salt = getNumberSalt(profile?.canvasSalt, 7);
    const adjust = (value, delta) => {
      if (!delta) return value;
      const increased = value + delta;
      return increased >= 0 && increased <= 255 ? increased : value - delta;
    };
    // A handful of deterministic pixels is sufficient to keep the exported
    // fingerprint stable. Avoid walking every pixel on large canvases.
    for (let sample = 0; sample < sampleCount; sample += 1) {
      const pixelIndex = (salt + sample * 104729) % pixelCount;
      const offset = pixelIndex * 4;
      data[offset] = adjust(data[offset], shift.r);
      data[offset + 1] = adjust(data[offset + 1], shift.g);
      data[offset + 2] = adjust(data[offset + 2], shift.b);
      if (shift.a) data[offset + 3] = adjust(data[offset + 3], shift.a);
    }
    return imageData;
  }

  function createSpoofedCanvas(sourceCanvas, profile) {
    if (!sourceCanvas || !sourceCanvas.width || !sourceCanvas.height || !originalGetImageData) return null;
    try {
      const shadowCanvas = document.createElement('canvas');
      shadowCanvas.width = sourceCanvas.width;
      shadowCanvas.height = sourceCanvas.height;
      const context = shadowCanvas.getContext('2d', { willReadFrequently: true });
      if (!context) return null;
      context.drawImage(sourceCanvas, 0, 0);
      const salt = getNumberSalt(profile?.canvasSalt, 7);
      const x = salt % sourceCanvas.width;
      const y = Math.floor(salt / Math.max(1, sourceCanvas.width)) % sourceCanvas.height;
      const pixel = originalGetImageData.call(context, x, y, 1, 1);
      patchCanvasPixels(pixel, profile);
      context.putImageData(pixel, x, y);
      return shadowCanvas;
    } catch (e) {
      return null;
    }
  }

  defineGetter(Navigator.prototype, 'language', () => {
    return state.languageEnabled && state.navigatorLanguage ? state.navigatorLanguage : original.language;
  });
  defineGetter(Navigator.prototype, 'languages', () => {
    return state.languageEnabled && state.navigatorLanguages.length ? state.navigatorLanguages.slice() : original.languages.slice();
  });

  try {
    Date.prototype.getTimezoneOffset = markNative(function() {
      if (shouldApplyFeature('timezone')) {
        const profile = state.fingerprintProfile;
        const stored = profile?.timezoneOffsetMinutes;
        if (stored != null && Number.isFinite(Number(stored))) {
          return Number(stored);
        }
        const timezone = String(profile?.timezone || '');
        const customOffset = computeTimezoneOffsetMinutes(timezone);
        if (customOffset != null) return customOffset;
      }
      return originalDateTimezoneOffset.call(this);
    }, 'getTimezoneOffset');
  } catch (e) {}

  try {
    Intl.DateTimeFormat.prototype.resolvedOptions = markNative(function(...args) {
      const options = originalIntlResolvedOptions.apply(this, args);
      if (shouldApplyFeature('timezone')) {
        options.timeZone = String(state.fingerprintProfile.timezone || options.timeZone || 'UTC');
      }
      return options;
    }, 'resolvedOptions');
  } catch (e) {}

  function installUserAgentPatches() {
    if (userAgentPatchesInstalled) return;
    userAgentPatchesInstalled = true;

    defineGetter(Navigator.prototype, 'userAgent', () => {
      return state.userAgentEnabled && state.userAgent ? state.userAgent : original.userAgent;
    });
    defineGetter(Navigator.prototype, 'appVersion', () => {
      return state.userAgentEnabled && state.userAgent ? state.userAgent.replace(/^Mozilla\//, '') : original.appVersion;
    });
    defineGetter(Navigator.prototype, 'platform', () => {
      return state.userAgentEnabled && state.platform ? state.platform : original.platform;
    });
    defineGetter(Navigator.prototype, 'vendor', () => {
      return state.userAgentEnabled && state.userAgent ? 'Google Inc.' : original.vendor;
    });
    defineGetter(Navigator.prototype, 'maxTouchPoints', () => {
      if (state.userAgentEnabled && state.userAgentData) {
        return state.userAgentData.mobile ? 5 : 0;
      }
      return Number(original.maxTouchPoints) || 0;
    });
    defineGetter(Navigator.prototype, 'userAgentData', () => {
      return state.userAgentEnabled && state.userAgentData
        ? buildNavigatorUAData(state.userAgentData)
        : original.userAgentData;
    });
  }

  function restoreUserAgentPatches() {
    if (!userAgentPatchesInstalled) return;
    restorePrototypeProperty(Navigator.prototype, 'userAgent', navigatorUserAgentDescriptor);
    restorePrototypeProperty(Navigator.prototype, 'appVersion', navigatorAppVersionDescriptor);
    restorePrototypeProperty(Navigator.prototype, 'platform', navigatorPlatformDescriptor);
    restorePrototypeProperty(Navigator.prototype, 'vendor', navigatorVendorDescriptor);
    restorePrototypeProperty(Navigator.prototype, 'maxTouchPoints', navigatorMaxTouchPointsDescriptor);
    restorePrototypeProperty(Navigator.prototype, 'userAgentData', navigatorUserAgentDataDescriptor);
    userAgentPatchesInstalled = false;
  }

  function updateUserAgentPatches() {
    if (state.userAgentEnabled && state.userAgent) {
      installUserAgentPatches();
    } else {
      restoreUserAgentPatches();
    }
  }

  function nativeScreenMetrics() {
    const nativeWidth = screenWidthDescriptor?.get ? Number(screenWidthDescriptor.get.call(window.screen)) : Number(window.screen?.width);
    const nativeHeight = screenHeightDescriptor?.get ? Number(screenHeightDescriptor.get.call(window.screen)) : Number(window.screen?.height);
    const nativeAvailWidth = screenAvailWidthDescriptor?.get ? Number(screenAvailWidthDescriptor.get.call(window.screen)) : nativeWidth;
    const nativeAvailHeight = screenAvailHeightDescriptor?.get ? Number(screenAvailHeightDescriptor.get.call(window.screen)) : nativeHeight;
    return {
      width: Number.isFinite(nativeWidth) ? nativeWidth : 1920,
      height: Number.isFinite(nativeHeight) ? nativeHeight : 1080,
      availWidth: Number.isFinite(nativeAvailWidth) ? nativeAvailWidth : nativeWidth,
      availHeight: Number.isFinite(nativeAvailHeight) ? nativeAvailHeight : nativeHeight
    };
  }

  function coherentScreenProfile() {
    const nativeMetrics = nativeScreenMetrics();
    const requested = state.fingerprintProfile?.screen || {};
    const requestedWidth = Number(requested.width) || nativeMetrics.width;
    const requestedHeight = Number(requested.height) || nativeMetrics.height;
    const minWidth = Math.max(1, Number(window.outerWidth) || 0);
    const minHeight = Math.max(1, Number(window.outerHeight) || 0);
    const standardScreens = [
      [1366, 768], [1440, 900], [1536, 864], [1600, 900], [1680, 1050],
      [1920, 1080], [1920, 1200], [2560, 1440], [2560, 1600], [3840, 2160]
    ];
    let width = requestedWidth;
    let height = requestedHeight;
    if (width < minWidth || height < minHeight) {
      const replacement = standardScreens.find(([w, h]) => w >= minWidth && h >= minHeight)
        || standardScreens[standardScreens.length - 1];
      width = replacement[0];
      height = replacement[1];
    }
    const taskbarWidth = Math.max(0, Math.min(160, nativeMetrics.width - nativeMetrics.availWidth));
    const taskbarHeight = Math.max(0, Math.min(160, nativeMetrics.height - nativeMetrics.availHeight));
    return {
      width,
      height,
      availWidth: Math.max(minWidth, width - taskbarWidth),
      availHeight: Math.max(minHeight, height - taskbarHeight),
      colorDepth: Number(requested.colorDepth) || 24,
      pixelDepth: Number(requested.pixelDepth) || 24
    };
  }

  function installStrictFingerprintPatches() {
    if (strictPatchesInstalled) return;
    strictPatchesInstalled = true;

    defineGetter(Navigator.prototype, 'hardwareConcurrency', () => {
      if (shouldApplyFeature('hardware')) {
        return Number(state.fingerprintProfile.hardwareConcurrency) || 8;
      }
      return navigatorHardwareDescriptor?.get ? navigatorHardwareDescriptor.get.call(navigator) : 8;
    });
    defineGetter(Navigator.prototype, 'deviceMemory', () => {
      if (shouldApplyFeature('hardware')) {
        return Number(state.fingerprintProfile.deviceMemory) || 8;
      }
      return navigatorMemoryDescriptor?.get ? navigatorMemoryDescriptor.get.call(navigator) : 8;
    });

  if (Screen?.prototype) {
    defineGetter(Screen.prototype, 'width', () => {
      if (shouldApplyFeature('screen') && state.fingerprintProfile.screen?.width) {
        return coherentScreenProfile().width;
      }
      return screenWidthDescriptor?.get ? screenWidthDescriptor.get.call(window.screen) : 1920;
    });
    defineGetter(Screen.prototype, 'height', () => {
      if (shouldApplyFeature('screen') && state.fingerprintProfile.screen?.height) {
        return coherentScreenProfile().height;
      }
      return screenHeightDescriptor?.get ? screenHeightDescriptor.get.call(window.screen) : 1080;
    });
    defineGetter(Screen.prototype, 'availWidth', () => {
      if (shouldApplyFeature('screen') && state.fingerprintProfile.screen?.width) {
        return coherentScreenProfile().availWidth;
      }
      return screenAvailWidthDescriptor?.get ? screenAvailWidthDescriptor.get.call(window.screen) : 1920;
    });
    defineGetter(Screen.prototype, 'availHeight', () => {
      if (shouldApplyFeature('screen') && state.fingerprintProfile.screen?.height) {
        return coherentScreenProfile().availHeight;
      }
      return screenAvailHeightDescriptor?.get ? screenAvailHeightDescriptor.get.call(window.screen) : 1080;
    });
    defineGetter(Screen.prototype, 'colorDepth', () => {
      if (shouldApplyFeature('screen') && state.fingerprintProfile.screen?.colorDepth) {
        return Number(state.fingerprintProfile.screen.colorDepth) || 24;
      }
      return screenColorDepthDescriptor?.get ? screenColorDepthDescriptor.get.call(window.screen) : 24;
    });
    defineGetter(Screen.prototype, 'pixelDepth', () => {
      if (shouldApplyFeature('screen') && state.fingerprintProfile.screen?.pixelDepth) {
        return Number(state.fingerprintProfile.screen.pixelDepth) || 24;
      }
      return screenPixelDepthDescriptor?.get ? screenPixelDepthDescriptor.get.call(window.screen) : 24;
    });
  }

  if (typeof HTMLElement !== 'undefined' && htmlOffsetWidthDescriptor?.get) {
    try {
      defineGetter(HTMLElement.prototype, 'offsetWidth', function() {
        const width = Number(htmlOffsetWidthDescriptor.get.call(this)) || 0;
        if (!shouldApplyFeature('font') || !width) return width;
        const seed = getNumberSalt(state.fingerprintProfile?.fontSalt, 173);
        const textLength = String(this.textContent || '').length;
        const tagWeight = String(this.tagName || '').length * 13;
        // Small deterministic +/-1 noise keeps layout metrics plausible while
        // retaining the old engine's font-dimension fingerprint behavior.
        const selector = (seed + textLength + tagWeight + Math.round(width)) % 11;
        if (selector !== 0 && selector !== 1) return width;
        return Math.max(0, width + (selector === 0 ? 1 : -1));
      });
    } catch (e) {}
  }

  try {
    HTMLCanvasElement.prototype.toDataURL = markNative(function(...args) {
      if (!shouldApplyFeature('canvas')) return originalCanvasToDataURL.apply(this, args);
      const exportCanvas = createSpoofedCanvas(this, state.fingerprintProfile) || this;
      return originalCanvasToDataURL.apply(exportCanvas, args);
    }, 'toDataURL');
  } catch (e) {}

  try {
    HTMLCanvasElement.prototype.toBlob = markNative(function(callback, type, quality) {
      if (!shouldApplyFeature('canvas')) return originalCanvasToBlob.call(this, callback, type, quality);
      const exportCanvas = createSpoofedCanvas(this, state.fingerprintProfile) || this;
      return originalCanvasToBlob.call(exportCanvas, callback, type, quality);
    }, 'toBlob');
  } catch (e) {}

  if (CanvasRenderingContext2D?.prototype?.getImageData && originalGetImageData) {
    try {
      CanvasRenderingContext2D.prototype.getImageData = markNative(function(...args) {
        const data = originalGetImageData.apply(this, args);
        if (shouldApplyFeature('canvas')) {
          return patchCanvasPixels(data, state.fingerprintProfile);
        }
        return data;
      }, 'getImageData');
    } catch (e) {}
  }

  if (AudioBuffer?.prototype?.getChannelData && originalGetChannelData) {
    try {
      AudioBuffer.prototype.getChannelData = markNative(function(...args) {
        const channelData = originalGetChannelData.apply(this, args);
        if (shouldApplyFeature('audio') && channelData?.length) {
          const spoofedData = new Float32Array(channelData);
          const salt = getNumberSalt(state.fingerprintProfile.audioSalt, 11);
          const index = salt % spoofedData.length;
          spoofedData[index] = spoofedData[index] + (salt % 1000) * 0.0000001;
          return spoofedData;
        }
        return channelData;
      }, 'getChannelData');
    } catch (e) {}
  }

  if (AnalyserNode?.prototype?.getFloatFrequencyData && originalGetFloatFrequencyData) {
    try {
      AnalyserNode.prototype.getFloatFrequencyData = markNative(function(array) {
        originalGetFloatFrequencyData.call(this, array);
        if (shouldApplyFeature('audio') && array?.length) {
          const salt = getNumberSalt(state.fingerprintProfile.audioSalt, 13);
          const index = salt % array.length;
          array[index] = array[index] + ((salt % 7) + 1) * 0.0001;
        }
      }, 'getFloatFrequencyData');
    } catch (e) {}
  }

  function patchWebGLBufferData(originalFn) {
    return markNative(function(...args) {
      if (shouldApplyFeature('webgl') && args[1] && ArrayBuffer.isView(args[1]) && args[1].length > 1) {
        try {
          const source = args[1];
          const copy = new source.constructor(source);
          const index = Math.min(1, copy.length - 1);
          const current = Number(copy[index]);
          if (Number.isFinite(current)) {
            const value = Number(state.fingerprintProfile?.webglBufferValue) || 0.01;
            // Stable, tiny buffer perturbation derived from the old MPS bufferData method.
            copy[index] = current + value * 0.0000001;
            args[1] = copy;
          }
        } catch (e) {}
      }
      return originalFn.apply(this, args);
    }, 'bufferData', originalFn);
  }

  // Keep native WebGL vendor/renderer/capability reporting. Spoofing those values
  // independently is a common cause of authenticity mismatches. Only the rendered
  // fingerprint buffer is varied, and it remains stable for the active device profile.
  if (WebGLRenderingContext?.prototype?.bufferData && originalWebGLBufferData) {
    try { WebGLRenderingContext.prototype.bufferData = patchWebGLBufferData(originalWebGLBufferData); } catch (e) {}
